export function rng(seed){let a=seed>>>0;return()=>{a=a+1831565813>>>0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}export function dailySeed(date=new Date){const y=date.getFullYear();const m=date.getMonth()+1;const d=date.getDate();return y*1e4+m*100+d}export function currentSeed(){const asked=new URLSearchParams(location.search).get("seed");const parsed=Number.parseInt(asked??"",10);return Number.isFinite(parsed)&&parsed>0?parsed:dailySeed()}export function isDaily(seed){return seed===dailySeed()}export function seedUrl(seed){const url=new URL(location.href);url.search="";url.searchParams.set("seed",String(seed));return url.toString()}export function shuffle(random,items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}export async function shareSeed(seed,title){const url=seedUrl(seed);const payload={title,text:`play this exact ${title} board with me`,url};try{if(navigator.share&&(!navigator.canShare||navigator.canShare(payload))){await navigator.share(payload);return"shared"}}catch(error){if(error&&error.name==="AbortError")return"cancelled"}try{await navigator.clipboard.writeText(url);return"copied"}catch{return"failed"}}
